CREATE TABLE moderation_cases (
  case_id TEXT PRIMARY KEY NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT NOT NULL,
  target_version INTEGER,
  policy_version TEXT NOT NULL,
  state TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 0,
  assigned_reviewer_id TEXT,
  current_decision_id TEXT,
  evidence_bundle_ref TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);

CREATE UNIQUE INDEX uq_moderation_cases_case_id
  ON moderation_cases(case_id);
CREATE INDEX ix_moderation_cases_queue
  ON moderation_cases(state, priority DESC, created_at ASC, case_id ASC);
CREATE INDEX ix_moderation_cases_reviewer_state
  ON moderation_cases(assigned_reviewer_id, state, priority DESC, created_at ASC);

CREATE TABLE moderation_decisions (
  decision_id TEXT PRIMARY KEY NOT NULL,
  case_id TEXT NOT NULL,
  case_version INTEGER NOT NULL,
  outcome TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT NOT NULL,
  target_version INTEGER,
  policy_version TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  severity TEXT NOT NULL,
  scope TEXT NOT NULL,
  effective_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ,
  source_kind TEXT NOT NULL,
  reviewer_id TEXT,
  reviewer_layer TEXT,
  request_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE(case_id, case_version)
);

CREATE UNIQUE INDEX uq_moderation_decisions_case_version
  ON moderation_decisions(case_id, case_version);
CREATE INDEX ix_moderation_decisions_case_created
  ON moderation_decisions(case_id, created_at);
CREATE INDEX ix_moderation_decisions_policy
  ON moderation_decisions(policy_version, created_at);

CREATE TABLE moderation_decision_idempotency (
  id TEXT PRIMARY KEY NOT NULL,
  reviewer_id TEXT NOT NULL,
  case_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  decision_id TEXT NOT NULL,
  response_status INTEGER NOT NULL,
  response_json TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  UNIQUE(reviewer_id, case_id, idempotency_key)
);

CREATE INDEX ix_moderation_idem_expiry
  ON moderation_decision_idempotency(expires_at);

CREATE TABLE moderation_txn_guard (
  id INTEGER PRIMARY KEY NOT NULL CHECK (id = 1),
  successful INTEGER NOT NULL CHECK (successful = 1)
);

CREATE TABLE moderation_enforcement_outbox (
  outbox_id TEXT PRIMARY KEY NOT NULL,
  decision_id TEXT NOT NULL UNIQUE,
  case_id TEXT NOT NULL,
  target_type TEXT NOT NULL CHECK (target_type = 'content'),
  target_id TEXT NOT NULL,
  target_version INTEGER NOT NULL CHECK (target_version >= 1),
  outcome TEXT NOT NULL CHECK (outcome IN ('APPROVED', 'REJECTED')),
  policy_version TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('PENDING', 'DELIVERED', 'RETRY')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_attempt_at TIMESTAMPTZ NOT NULL,
  last_error TEXT,
  created_at TIMESTAMPTZ NOT NULL,
  delivered_at TIMESTAMPTZ
);

CREATE INDEX ix_moderation_enforcement_outbox_ready
  ON moderation_enforcement_outbox(status, next_attempt_at);

CREATE TABLE moderation_reports (
  report_id TEXT PRIMARY KEY NOT NULL,
  actor_user_id TEXT NOT NULL,
  target_type TEXT NOT NULL
    CHECK (target_type IN ('content', 'comment', 'creator', 'media', 'profile')),
  target_id TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  description TEXT,
  evidence_refs_json JSONB NOT NULL DEFAULT '[]'::jsonb
    CHECK (jsonb_typeof(evidence_refs_json) = 'array'),
  policy_version TEXT NOT NULL,
  dedup_bucket TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE(actor_user_id, target_type, target_id, reason_code, dedup_bucket)
);

CREATE INDEX ix_moderation_reports_target_created
  ON moderation_reports(target_type, target_id, created_at);
CREATE INDEX ix_moderation_reports_actor_created
  ON moderation_reports(actor_user_id, created_at);

CREATE TABLE moderation_report_idempotency (
  id TEXT PRIMARY KEY NOT NULL,
  actor_user_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  report_id TEXT NOT NULL,
  response_status INTEGER NOT NULL,
  response_json TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  UNIQUE(actor_user_id, idempotency_key)
);

CREATE INDEX ix_moderation_report_idem_expiry
  ON moderation_report_idempotency(expires_at);

COMMENT ON TABLE moderation_cases IS
  'W06-owned D1-03 moderation queue source. Identity and target IDs are opaque references; no cross-domain foreign keys.';
COMMENT ON TABLE moderation_decisions IS
  'W06-owned authoritative moderation decisions. AuditEvent is separately owned by W09.';
COMMENT ON TABLE moderation_reports IS
  'W06-owned user reports. evidence_refs_json is constrained to a JSON array; raw evidence blobs are not stored here.';
COMMENT ON TABLE moderation_enforcement_outbox IS
  'W06-owned transactional enforcement outbox. W03 content state remains authoritative in W03.';
